actions.script:
import java.math.BigDecimal
import java.math.RoundingMode

// Get all products that have BOMs (manufactured items)
def bomList = ec.entity.find("zenith.erp.manufacturing.BillOfMaterial")
    .condition("isActive", "Y")
    .list()

def processedProducts = new HashSet()
def totalShortage = BigDecimal.ZERO

for (def bom : bomList) {
    if (processedProducts.contains(bom.productId)) continue
    processedProducts.add(bom.productId)

    // Get current stock
    def assets = ec.entity.find("mantle.product.asset.Asset")
        .condition("productId", bom.productId)
    if (facilityId) assets.condition("facilityId", facilityId)
    def assetList = assets.list()

    def currentStock = BigDecimal.ZERO
    for (def a : assetList) {
        currentStock = currentStock.add(a.availableToPromiseTotal ?: BigDecimal.ZERO)
    }

    // Get pending work orders (already in pipeline)
    def pendingWoQty = BigDecimal.ZERO
    if (includeExistingOrders) {
        def pendingWos = ec.entity.find("zenith.erp.manufacturing.WorkOrder")
            .condition("productId", bom.productId)
            .condition("statusId", "in", ["WoDraft", "WoReleased", "WoInProgress"])
            .list()
        for (def wo : pendingWos) {
            pendingWoQty = pendingWoQty.add((wo.quantity ?: BigDecimal.ZERO).subtract(wo.completedQuantity ?: BigDecimal.ZERO))
        }
    }

    // Get demand from forecasts
    def forecastDemand = BigDecimal.ZERO
    def forecasts = ec.entity.find("zenith.erp.inventory.DemandForecast")
        .condition("productId", bom.productId)
        .condition("periodStart", "less-equals", horizonDate)
        .condition("periodEnd", "greater-equals", new java.sql.Date(System.currentTimeMillis()))
        .list()
    for (def fc : forecasts) {
        forecastDemand = forecastDemand.add(fc.forecastQuantity ?: BigDecimal.ZERO)
    }

    // Check reorder point
    def product = ec.entity.find("mantle.product.Product")
        .condition("productId", bom.productId).one()
    def reorderPoint = product?.reorderPoint ?: BigDecimal.ZERO
    def reorderQty = product?.reorderQuantity ?: new BigDecimal("100")

    // Net requirement = max(demand, reorderPoint) - currentStock - pendingOrders
    def totalDemand = forecastDemand.max(reorderPoint)
    def netRequirement = totalDemand.subtract(currentStock).subtract(pendingWoQty)

    if (netRequirement.compareTo(BigDecimal.ZERO) > 0) {
        // Round up to reorder quantity
        def plannedQty = netRequirement.max(reorderQty)
        totalShortage = totalShortage.add(netRequirement)

        // Create planned manufacturing order
        ec.entity.makeValue("zenith.erp.manufacturing.PlannedOrder")
            .setAll([productId: bom.productId, bomId: bom.bomId,
                     facilityId: facilityId, requiredQuantity: totalDemand,
                     availableStock: currentStock.add(pendingWoQty),
                     netRequirement: netRequirement, plannedQuantity: plannedQty,
                     requiredDate: horizonDate,
                     plannedStartDate: new java.sql.Date(System.currentTimeMillis() + (7L * 86400000L)),
                     leadTimeDays: 7, orderType: "Manufacture",
                     sourceType: "MRP", mrpRunId: mrpRunId,
                     statusId: "PoPlanned", priority: "Normal"])
            .setSequencedIdPrimary().create()
        plannedOrdersCreated++

        // Explode BOM to check raw material availability
        def bomItems = ec.entity.find("zenith.erp.manufacturing.BomItem")
            .condition("bomId", bom.bomId).list()

        for (def bi : bomItems) {
            def materialQtyNeeded = (bi.quantity ?: BigDecimal.ONE).multiply(plannedQty)
                .divide(bom.outputQuantity ?: BigDecimal.ONE, 2, RoundingMode.HALF_UP)

            // Add waste factor
            if (bi.wastePercent && bi.wastePercent > 0) {
                materialQtyNeeded = materialQtyNeeded.multiply(
                    BigDecimal.ONE.add(bi.wastePercent.divide(new BigDecimal("100"), 4, RoundingMode.HALF_UP)))
            }

            // Check raw material stock
            def rmAssets = ec.entity.find("mantle.product.asset.Asset")
                .condition("productId", bi.productId)
            if (facilityId) rmAssets.condition("facilityId", facilityId)
            def rmStock = BigDecimal.ZERO
            for (def rma : rmAssets.list()) {
                rmStock = rmStock.add(rma.availableToPromiseTotal ?: BigDecimal.ZERO)
            }

            def rmShortage = materialQtyNeeded.subtract(rmStock)
            if (rmShortage.compareTo(BigDecimal.ZERO) > 0) {
                // Check if this material has its own BOM (sub-assembly)
                def subBom = ec.entity.find("zenith.erp.manufacturing.BillOfMaterial")
                    .condition("productId", bi.productId)
                    .condition("isActive", "Y")
                    .condition("isDefault", "Y").one()

                def ot = subBom ? "Manufacture" : "Purchase"
                ec.entity.makeValue("zenith.erp.manufacturing.PlannedOrder")
                    .setAll([productId: bi.productId, bomId: subBom?.bomId,
                             facilityId: facilityId, requiredQuantity: materialQtyNeeded,
                             availableStock: rmStock, netRequirement: rmShortage,
                             plannedQuantity: rmShortage,
                             requiredDate: new java.sql.Date(System.currentTimeMillis() + (5L * 86400000L)),
                             plannedStartDate: new java.sql.Date(System.currentTimeMillis() + (2L * 86400000L)),
                             leadTimeDays: subBom ? 5 : 10,
                             orderType: ot, sourceType: "MRP", mrpRunId: mrpRunId,
                             statusId: "PoPlanned", priority: "Normal"])
                    .setSequencedIdPrimary().create()

                if (ot == "Purchase") purchaseOrdersCreated++
                else plannedOrdersCreated++
            }
        }
    }

    productsAnalyzed++
}

// Update MRP Run totals
def mrpRun = ec.entity.find("zenith.erp.manufacturing.MrpRun")
    .condition("mrpRunId", mrpRunId).one()
mrpRun.productsAnalyzed = productsAnalyzed
mrpRun.plannedOrdersCreated = plannedOrdersCreated
mrpRun.purchaseOrdersCreated = purchaseOrdersCreated
mrpRun.totalShortage = totalShortage
mrpRun.update()

iterate.script:
import java.math.BigDecimal
import java.math.RoundingMode

def today = new java.sql.Date(System.currentTimeMillis())
def endDate = new java.sql.Date(System.currentTimeMillis() + ((long)planningDays * 86400000L))

// Get all active/released work orders using this work center
def woOps = ec.entity.find("zenith.erp.manufacturing.WorkOrderOperation")
    .condition("workCenterId", wc.workCenterId)
    .condition("statusId", "in", ["OpPending", "OpInProgress"])
    .list()

def totalPlannedMinutes = 0
for (def op : woOps) {
    totalPlannedMinutes += (op.plannedMinutes ?: 0)
}

def plannedHours = new BigDecimal(totalPlannedMinutes).divide(new BigDecimal("60"), 2, RoundingMode.HALF_UP)
def availableHours = (wc.capacityPerHour ?: new BigDecimal("8")).multiply(new BigDecimal(planningDays))
def utilization = availableHours > 0 ?
    plannedHours.divide(availableHours, 4, RoundingMode.HALF_UP).multiply(new BigDecimal("100")).setScale(1, RoundingMode.HALF_UP) :
    BigDecimal.ZERO
def overloaded = utilization.compareTo(new BigDecimal("100")) > 0 ? "Y" : "N"

// Upsert capacity plan
def existing = ec.entity.find("zenith.erp.manufacturing.CapacityPlan")
    .condition("workCenterId", wc.workCenterId)
    .condition("planDate", today).one()

if (existing) {
    existing.availableHours = availableHours
    existing.plannedHours = plannedHours
    existing.utilizationPercent = utilization
    existing.overloadFlag = overloaded
    existing.update()
} else {
    ec.entity.makeValue("zenith.erp.manufacturing.CapacityPlan")
        .setAll([workCenterId: wc.workCenterId, planDate: today,
                 availableHours: availableHours, plannedHours: plannedHours,
                 utilizationPercent: utilization, overloadFlag: overloaded])
        .setSequencedIdPrimary().create()
}

workCentersAnalyzed++
if (overloaded == "Y") overloadedCenters++
